def metric(data: pd.DataFrame) -> float:
    import numpy as np

    def get_ttb_pred(a, b):
        for i in range(4):
            if a[i] > b[i]: return 0
            if b[i] > a[i]: return 1
        return 0.5

    def get_ew_pred(a, b):
        sa, sb = sum(a), sum(b)
        if sa > sb: return 0
        if sb > sa: return 1
        return 0.5

    ttb_match = []
    for _, row in data.iterrows():
        a = row['option_a_ratings']
        b = row['option_b_ratings']
        resp = row['response']

        ttb = get_ttb_pred(a, b)
        ew = get_ew_pred(a, b)

        if ttb != ew and ttb != 0.5:
            ttb_match.append(1 if resp == ttb else 0)

    if not ttb_match:
        return 0.5
    return np.mean(ttb_match)

